//! `tutela codegen`: typed constants and the route table from one manifest
//! (PERMISSION-MODEL.md 14.1).
//!
//! Both outputs come from the same compiled model, so the React constants
//! and the server's route guards cannot drift apart. The output is
//! deterministic. Names never hold `__`, so a constant `TYPE__NAME` is
//! unique within its group. Every string is escaped for its language, and no
//! manifest text goes into a comment.

use std::fmt::Write as _;

use tutela_pdp::model::{Method, Model, WhenDenied};

/// The header line of every generated file.
const HEADER: &str = "Generated by `tutela codegen`. Do not edit; run `tutela codegen` again.";

/// One action, field, feature or UI key and its constant name.
struct Key {
    constant: String,
    value: String,
}

/// The keys of a model, sorted.
struct Keys {
    actions: Vec<Key>,
    fields: Vec<Key>,
    features: Vec<Key>,
    ui: Vec<Key>,
}

/// `a.b_c` → `A__B_C`; `type:action` → `TYPE__ACTION`.
fn constant(parts: &[&str]) -> String {
    parts
        .iter()
        .map(|p| p.trim_start_matches('@').to_ascii_uppercase())
        .collect::<Vec<_>>()
        .join("__")
}

fn keys(model: &Model) -> Keys {
    let mut actions = Vec::new();
    let mut fields = Vec::new();
    let mut features = Vec::new();
    for (ty, def) in model.types() {
        let t = ty.as_str();
        for builtin in ["read", "write", "delete", "manage_access"] {
            actions.push(Key {
                constant: constant(&[t, builtin]),
                value: format!("{t}:{builtin}"),
            });
        }
        for a in def.actions.keys() {
            actions.push(Key {
                constant: constant(&[t, a.as_str()]),
                value: format!("{t}:{a}"),
            });
        }
        for f in def.fields.keys() {
            fields.push(Key {
                constant: constant(&[t, f.as_str()]),
                value: format!("{t}.{f}"),
            });
        }
        for f in &def.features {
            features.push(Key {
                constant: constant(&[t, f.as_str()]),
                value: format!("{t}.{f}"),
            });
        }
    }
    let ui = model
        .ui()
        .keys()
        .map(|k| Key {
            constant: constant(&k.as_str().split('.').collect::<Vec<_>>()),
            value: k.to_string(),
        })
        .collect();
    for group in [&mut actions, &mut fields, &mut features] {
        group.sort_by(|a, b| a.constant.cmp(&b.constant));
    }
    Keys {
        actions,
        fields,
        features,
        ui,
    }
}

const fn method(m: Method) -> &'static str {
    match m {
        Method::Get => "GET",
        Method::Post => "POST",
        Method::Put => "PUT",
        Method::Patch => "PATCH",
        Method::Delete => "DELETE",
    }
}

const fn when_denied(w: WhenDenied) -> &'static str {
    match w {
        WhenDenied::Show => "show",
        WhenDenied::Disable => "disable",
        WhenDenied::Hide => "hide",
        WhenDenied::Readonly => "readonly",
    }
}

/// A Rust string literal.
fn rs(s: &str) -> String {
    format!("{s:?}")
}

/// A JavaScript string literal.
fn js(s: &str) -> String {
    serde_json::to_string(s).unwrap_or_else(|_| "\"\"".to_owned())
}

/// The Rust module. `digest` is the manifest's SHA-256.
#[must_use]
pub fn rust(model: &Model, digest: &str) -> String {
    let k = keys(model);
    let mut o = String::new();
    let _ = writeln!(o, "// {HEADER}");
    let _ = writeln!(
        o,
        "// Include it as a module, for example `pub mod perms;`."
    );
    let _ = writeln!(o);
    let _ = writeln!(o, "/// The app (the model namespace).");
    let _ = writeln!(o, "pub const APP: &str = {};", rs(model.app().as_str()));
    let _ = writeln!(o, "/// SHA-256 of the manifest these constants come from.");
    let _ = writeln!(o, "pub const MANIFEST_SHA256: &str = {};", rs(digest));
    for (module, doc, group) in [
        ("actions", "Action keys (`type:action`).", &k.actions),
        ("fields", "Data field keys (`type.field`).", &k.fields),
        ("features", "Feature keys (`type.@feature`).", &k.features),
        (
            "ui",
            "UI keys. Hiding a component is never security.",
            &k.ui,
        ),
    ] {
        let _ = writeln!(o);
        let _ = writeln!(o, "/// {doc}");
        let _ = writeln!(o, "pub mod {module} {{");
        for key in group {
            let _ = writeln!(o, "    /// The key {}.", key.value.replace('`', ""));
            let _ = writeln!(
                o,
                "    pub const {}: &str = {};",
                key.constant,
                rs(&key.value)
            );
        }
        let _ = writeln!(o, "}}");
    }
    let _ = writeln!(o);
    let _ = writeln!(o, "/// A route the manifest declares, with what guards it.");
    let _ = writeln!(o, "#[derive(Clone, Copy, PartialEq, Eq, Debug)]");
    let _ = writeln!(o, "pub struct Route {{");
    let _ = writeln!(o, "    /// The HTTP method.");
    let _ = writeln!(o, "    pub method: &'static str,");
    let _ = writeln!(o, "    /// The path, with `{{name}}` placeholders.");
    let _ = writeln!(o, "    pub path: &'static str,");
    let _ = writeln!(o, "    /// The UI key that declares it.");
    let _ = writeln!(o, "    pub ui_key: &'static str,");
    let _ = writeln!(o, "    /// The actions the route needs.");
    let _ = writeln!(o, "    pub actions: &'static [&'static str],");
    let _ = writeln!(
        o,
        "    /// The fields and features the route shows or changes."
    );
    let _ = writeln!(o, "    pub fields: &'static [&'static str],");
    let _ = writeln!(o, "}}");
    let _ = writeln!(o);
    let _ = writeln!(o, "/// Every declared route. The server guards each one.");
    let _ = writeln!(o, "pub const ROUTES: &[Route] = &[");
    for (key, c) in model.ui() {
        let actions: Vec<String> = c.actions.iter().map(|a| rs(&a.to_string())).collect();
        let fields: Vec<String> = c.fields.iter().map(|f| rs(&f.to_string())).collect();
        for r in &c.routes {
            let _ = writeln!(o, "    Route {{");
            let _ = writeln!(o, "        method: {},", rs(method(r.method)));
            let _ = writeln!(o, "        path: {},", rs(&r.path));
            let _ = writeln!(o, "        ui_key: {},", rs(key.as_str()));
            let _ = writeln!(o, "        actions: &[{}],", actions.join(", "));
            let _ = writeln!(o, "        fields: &[{}],", fields.join(", "));
            let _ = writeln!(o, "    }},");
        }
    }
    let _ = writeln!(o, "];");
    let _ = writeln!(o);
    let _ = writeln!(
        o,
        "/// The declared routes as `(method, path)` pairs: for `tutela_sdk::http::Guards::declared`,"
    );
    let _ = writeln!(
        o,
        "/// and for the test that calls each route as a denied principal,"
    );
    let _ = writeln!(
        o,
        "/// `tutela_sdk::http::assert_routes_deny(app, route_pairs(), token)`."
    );
    let _ = writeln!(
        o,
        "pub fn route_pairs() -> impl Iterator<Item = (&'static str, &'static str)> {{"
    );
    let _ = writeln!(o, "    ROUTES.iter().map(|r| (r.method, r.path))");
    let _ = writeln!(o, "}}");
    o
}

/// The TypeScript module. `digest` is the manifest's SHA-256.
#[must_use]
pub fn typescript(model: &Model, digest: &str) -> String {
    let k = keys(model);
    let mut o = String::new();
    let _ = writeln!(o, "// {HEADER}");
    let _ = writeln!(o);
    let _ = writeln!(
        o,
        "export const APP = {} as const;",
        js(model.app().as_str())
    );
    let _ = writeln!(o, "export const MANIFEST_SHA256 = {} as const;", js(digest));
    for (name, ty, group) in [
        ("ACTIONS", "ActionKey", &k.actions),
        ("FIELDS", "FieldKey", &k.fields),
        ("FEATURES", "FeatureKey", &k.features),
    ] {
        let _ = writeln!(o);
        if group.is_empty() {
            let _ = writeln!(o, "export const {name} = {{}} as const;");
            let _ = writeln!(o, "export type {ty} = never;");
            continue;
        }
        let _ = writeln!(o, "export const {name} = {{");
        for key in group {
            let _ = writeln!(o, "  {}: {},", key.constant, js(&key.value));
        }
        let _ = writeln!(o, "}} as const;");
        let _ = writeln!(
            o,
            "export type {ty} = (typeof {name})[keyof typeof {name}];"
        );
    }
    let _ = writeln!(o);
    let _ = writeln!(
        o,
        "export type WhenDenied = \"show\" | \"disable\" | \"hide\" | \"readonly\";"
    );
    let _ = writeln!(o);
    let _ = writeln!(o, "export interface UiEntry {{");
    let _ = writeln!(o, "  readonly actions: readonly ActionKey[];");
    let _ = writeln!(o, "  readonly fields: readonly (FieldKey | FeatureKey)[];");
    let _ = writeln!(
        o,
        "  readonly routes: readonly {{ readonly method: string; readonly path: string }}[];"
    );
    let _ = writeln!(o, "  readonly whenDenied: WhenDenied;");
    let _ = writeln!(o, "  readonly reason: string | null;");
    let _ = writeln!(o, "}}");
    let _ = writeln!(o);
    let _ = writeln!(
        o,
        "// UI keys. Hiding a component is never security: the server checks again."
    );
    let _ = writeln!(o, "export const UI = {{");
    for (key, c) in model.ui() {
        let actions: Vec<String> = c.actions.iter().map(|a| js(&a.to_string())).collect();
        let fields: Vec<String> = c.fields.iter().map(|f| js(&f.to_string())).collect();
        let routes: Vec<String> = c
            .routes
            .iter()
            .map(|r| {
                format!(
                    "{{ method: {}, path: {} }}",
                    js(method(r.method)),
                    js(&r.path)
                )
            })
            .collect();
        let _ = writeln!(o, "  {}: {{", js(key.as_str()));
        let _ = writeln!(o, "    actions: [{}],", actions.join(", "));
        let _ = writeln!(o, "    fields: [{}],", fields.join(", "));
        let _ = writeln!(o, "    routes: [{}],", routes.join(", "));
        let _ = writeln!(o, "    whenDenied: {},", js(when_denied(c.when_denied)));
        let _ = writeln!(
            o,
            "    reason: {},",
            c.reason.as_deref().map_or_else(|| "null".to_owned(), js)
        );
        let _ = writeln!(o, "  }},");
    }
    let _ = writeln!(o, "}} as const satisfies Record<string, UiEntry>;");
    let _ = writeln!(o, "export type UiKey = keyof typeof UI;");
    o
}

#[cfg(test)]
pub mod golden {
    //! The generated Rust for the starter manifest, compiled under the
    //! workspace lints, as a product includes it (`pub mod perms;`).
    include!("../testdata/starter.rs");
}

#[cfg(test)]
mod tests {
    use tutela_pdp::model::Model;

    use super::*;
    use crate::init::starter;

    fn starter_model() -> (Model, String, String) {
        let src = starter("crm");
        let m = Model::from_toml(&src).unwrap();
        let d = tutela_store::digest(&src);
        (m, src, d)
    }

    #[test]
    fn the_golden_files_are_current() {
        let (m, _, d) = starter_model();
        assert_eq!(rust(&m, &d), include_str!("../testdata/starter.rs"));
        assert_eq!(typescript(&m, &d), include_str!("../testdata/starter.ts"));
    }

    #[test]
    fn the_route_table_comes_from_the_ui_entry() {
        assert_eq!(golden::APP, "crm");
        assert_eq!(golden::actions::TASK__CLOSE, "task:close");
        assert_eq!(golden::fields::TASK__ASSIGNEE, "task.assignee");
        assert_eq!(golden::ui::TASKS__CLOSE_BUTTON, "tasks.close_button");
        assert_eq!(
            golden::route_pairs().collect::<Vec<_>>(),
            [("POST", "/api/tasks/{id}/close")]
        );
        assert_eq!(
            golden::ROUTES,
            [golden::Route {
                method: "POST",
                path: "/api/tasks/{id}/close",
                ui_key: "tasks.close_button",
                actions: &["task:close"],
                fields: &[],
            }]
        );
    }

    #[test]
    fn strings_are_escaped_and_never_in_comments() {
        let src = starter("crm").replace(
            "reason      = \"Only editors can close tasks.\"",
            "reason      = \"Say \\\"no\\\" \\\\ */ </script> ${x}\"",
        );
        let m = Model::from_toml(&src).unwrap();
        let ts = typescript(&m, "d");
        assert!(
            ts.contains(r#"reason: "Say \"no\" \\ */ </script> ${x}","#),
            "{ts}"
        );
        let rs = rust(&m, "d");
        assert!(
            !rs.contains("Say"),
            "the reason is not a Rust constant: {rs}"
        );
    }

    #[test]
    fn features_get_their_own_group() {
        let src = starter("crm").replace(
            "[types.task]\nparent = \"project\"",
            "[types.task]\nparent = \"project\"\nfeatures = [\"ai\"]",
        );
        let m = Model::from_toml(&src).unwrap();
        let rs = rust(&m, "d");
        assert!(
            rs.contains("pub const TASK__AI: &str = \"task.@ai\";"),
            "{rs}"
        );
        let ts = typescript(&m, "d");
        assert!(ts.contains("TASK__AI: \"task.@ai\","), "{ts}");
    }
}
